head.script:
scwin.trigger1_onclick = function(e) {
    var str = "dl_gridData.setJSON before : " + chkCombo1.getValue();
    str += "<br/>";
    dl_gridData.setJSON(jsonData);
    str += "dl_gridData.setJSON( jsonData ); 실행 ";
    str += "<br/>";
    str += "dl_gridData.setJSON after : " + chkCombo1.getValue();
    txt1.setValue(str);
};
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).textContent == value) {
        return true;
    }
    return false
}
scwin.__select = function(id) {
    if (WebSquare.wUnit.getDomById($p.id + id).checked) {
        return true;
    }
    return false;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 checkCombobox 에 데이터 "a2", "a3" 을 선택한다.
    //1. In the browser, select data "a2", "a3" in checkCombobox.
    //Verify step 1. Data "a2" and "a3" are selected.
    //Test step 2. dl_gridData.setJSON 버튼을 클릭한다.
    //2. Click the dl_gridData.setJSON button.
    //Verify step 2. "a1", "a2", and "a3" are entered in the grid view.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_cell_0_0', 'a1')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_cell_1_0', 'a2')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_cell_2_0', 'a3')", "true");
    //Test step 3. 다시 checkCombobox 의 리스트를 펼친다.
    //3. Expand the checkCombobox list again.
    //Verify step 3. The 'a2' and 'a3' check boxes are selected.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chkCombo1').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.__select($p.id+'chkCombo1_itemTable_1_checkbox')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__select($p.id+'chkCombo1_itemTable_2_checkbox')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "col1": "a1"
    }, {
        "col1": "a2"
    }, {
        "col1": "a3"
    }];
    dataList2.setJSON(jsonData);
    chkCombo1.setValue("a2 a3");
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 08-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
